"""The Build tab's guide files (dm/android/app/src/main/assets/builds/*.json, BuildGuide.java's format, generated by
dm/android/tools/gen_build_guides.py).

Always: the format BuildGuide.parse accepts (class codes, rising stage ends, stat codes, links on maxroll.gg).
With DM_DECK_DIR=<an import pack's overlay/deck folder> (made from the player's own game files, so not in the repository): every
skill step against the game's skill rules (deck/skillrules.tsv): the class's own skill, at most its highest base level, every
prerequisite already planned before it since the last respec, and reachable by the stage's last level (the D2 rule: the n-th point
needs the skill's required level + n - 1). Item names the game does not know (deck/itemnames.tsv) are listed, not failed: shop
items such as "Coral Belt of the Mammoth" are written as text on purpose.
"""
import json
import os
import re
from pathlib import Path
from urllib.parse import urlparse
import unittest

BUILDS = Path(__file__).resolve().parents[1] / 'app' / 'src' / 'main' / 'assets' / 'builds'
CLASSES = ('ama', 'sor', 'nec', 'pal', 'bar', 'dru', 'ass', 'war')
STATS = ('str', 'dex', 'vit', 'ene')
DECK = os.environ.get('DM_DECK_DIR')


def guides():
    return {p.name: json.loads(p.read_text(encoding='utf-8')) for p in sorted(BUILDS.glob('*.json'))}


def texts(g):
    """Every note and tip of a guide (where "[Item]" may name a game item)."""
    out = [g['merc'].get('note', '')] + [x.get('note', '') for x in g['merc']['gear']]
    for s in g['stages']:
        out += s['tips'] + s.get('gearTips', []) + s.get('bpTips', []) + [x.get('note', '') for x in s['gear'] + s['stats']]
    return out


def effective(stages, i):
    """BuildPlan.steps: the steps from the last respec stage at or before i, up to i."""
    start = max([k for k in range(i + 1) if stages[k].get('respec')] or [0])
    return [step for k in range(start, i + 1) for step in stages[k].get('skills', [])]


class Format(unittest.TestCase):
    def test_every_class_has_a_build(self):
        self.assertEqual(sorted({g['class'] for g in guides().values()}), sorted(CLASSES))

    def test_files_match_the_reader(self):
        ids = set()
        for name, g in guides().items():
            with self.subTest(name):
                self.assertEqual(name, g['id'] + '.json')
                self.assertNotIn(g['id'], ids); ids.add(g['id'])
                self.assertIn(g['class'], CLASSES)
                self.assertTrue(g['name'] and g['summary'])
                ends = [s['to'] for s in g['stages'][:-1]]
                self.assertEqual(ends, sorted(set(ends)), 'stage ends must rise')
                self.assertNotIn('to', g['stages'][-1], 'the last stage is open-ended')
                for s in g['stages']:
                    for step in s['skills']:
                        self.assertIsInstance(step['skill'], int); self.assertGreaterEqual(step['to'], 1)
                    for r in s['stats']:
                        self.assertIn(r['stat'], STATS)
                        self.assertTrue(('to' in r) + bool(r.get('gear')) + bool(r.get('rest')) == 1, r)
                    for gear in s['gear']:
                        self.assertTrue(gear['slot'] and (gear['items'] or gear.get('note')))   # no items: a note under a heading
                bp = g['breakpoints']
                for k in ('fcr', 'fhr'):
                    if k not in bp:
                        continue            # a build that does not need this table leaves it out (BuildTab hides the row)
                    self.assertEqual(bp[k], sorted(bp[k]))
                    self.assertIn(bp[k + 'Target'], bp[k])

    def test_links_open_in_the_guide_view(self):
        for name, g in guides().items():
            self.assertTrue(g['links'], name)
            for link in g['links']:
                u = urlparse(link['url'])
                self.assertEqual(u.scheme, 'https', name)
                self.assertTrue(u.hostname == 'maxroll.gg' or u.hostname.endswith('.maxroll.gg'), name)   # GuideWeb.allowed


@unittest.skipUnless(DECK, 'set DM_DECK_DIR to an import pack overlay/deck folder to check against the game')
class AgainstTheGame(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        rows = (Path(DECK) / 'skillrules.tsv').read_text(encoding='utf-8').rstrip('\n').split('\n')[1:]
        cls.rules = {int(f[0]): (f[1], int(f[2]), int(f[3]), [int(x) for x in f[4:7]]) for f in (r.split('\t') for r in rows)}
        names = (Path(DECK) / 'itemnames.tsv').read_text(encoding='utf-8').rstrip('\n').split('\n')[1:]
        cls.items = {r.split('\t', 1)[0] for r in names}

    def test_skill_steps(self):
        for name, g in guides().items():
            stages = g['stages']
            for i, s in enumerate(stages):
                plan = {}
                for step in effective(stages, i - 1) if i and not s.get('respec') else []:
                    plan[step['skill']] = max(plan.get(step['skill'], 0), step['to'])
                for step in s['skills']:
                    sk, n = step['skill'], step['to']
                    with self.subTest(build=name, stage=s['name'], skill=sk, to=n):
                        cl, req, mx, pre = self.rules[sk]
                        self.assertEqual(cl, g['class'])
                        self.assertLessEqual(n, mx)
                        for p in pre:
                            if p >= 0:
                                self.assertGreaterEqual(plan.get(p, 0), 1, 'prerequisite %d not planned before %d' % (p, sk))
                        if 'to' in s:
                            self.assertLessEqual(req + n - 1, s['to'], 'needs level %d' % (req + n - 1))
                    plan[sk] = max(plan.get(sk, 0), n)
            for sk in g['after20']:
                self.assertEqual(self.rules[sk][0], g['class'], name)

    def test_item_names(self):
        unknown = set()
        for g in guides().values():
            for gear in [x for s in g['stages'] for x in s['gear']] + g['merc']['gear']:
                for item in gear['items']:
                    for part in item.split('|'):
                        if re.sub(r'[^a-z0-9]+', '', part.lower()) not in self.items:
                            unknown.add(part)
        print('\nshown as written (not game item names): ' + ', '.join(sorted(unknown)))

    def test_items_named_in_notes(self):
        # "[Item]" in a note or tip must be a game name, or it shows without its runes
        for name, g in guides().items():
            for t in texts(g):
                for item in re.findall(r'\[([^\]]*)\]', t):
                    with self.subTest(build=name, item=item):
                        self.assertIn(re.sub(r'[^a-z0-9]+', '', item.lower()), self.items)


if __name__ == '__main__':
    unittest.main()
